    String getAccHolder(); int getAccNo(); double getBalance();
    default double getInterestRate() { return 4.5; }
}

abstract class Account {
    // █ FILLED BY STUDENT: abstract deposit(), abstract withdraw(), concrete cautionMessage()
    public abstract void deposit(double a); public abstract void withdraw(double a);
    public void cautionMessage() { System.out.println("If action not performed by you, inform bank immediately!"); }
}

class Type_1 extends Account implements accountDetails {
    private int Acc_No; private String Acc_Holder; private final double Rate = 4.67; private double Balance;
    public Type_1(int n, String h, double b) { Acc_No=n; Acc_Holder=h; Balance=b; }
    public String getAccHolder() { return Acc_Holder; }
    public int getAccNo() { return Acc_No; }
    public double getBalance() { return Balance; }
    // █ FILLED BY STUDENT: deposit method
    public void deposit(double a) {
        if(a>=1000) { Balance+=a; System.out.println("Amount deposited successfully!"); }
        else System.out.println("Insufficient funds to deposit! Deposit unsuccessful");
        cautionMessage();
    }
    // █ FILLED BY STUDENT: withdraw method
    public void withdraw(double a) {
        if(a>Balance) System.out.println("Insufficient funds! Withdraw unsuccessful");
        else { Balance-=a; System.out.println("Withdraw successful"); }
        cautionMessage();
    }
}

class Type_2 extends Account implements accountDetails {
    private int Acc_No; private String Acc_Holder; private double Balance;
    public Type_2(int n, String h, double b) { Acc_No=n; Acc_Holder=h; Balance=b; }
    public String getAccHolder() { return Acc_Holder; }
    public int getAccNo() { return Acc_No; }
    public double getBalance() { return Balance; }
    // █ FILLED BY STUDENT: deposit method
    public void deposit(double a) {
        if(a>=1000) { Balance+=a; System.out.println("Amount deposited successfully!"); }
        else System.out.println("Insufficient funds to deposit! Deposit unsuccessful");
        cautionMessage();
    }
    // █ FILLED BY STUDENT: withdraw method
    public void withdraw(double a) {
        if(a>Balance) System.out.println("Insufficient funds! Withdraw unsuccessful");
        else if(a<20000) { Balance-=a; System.out.println("Withdraw successful"); }
        else System.out.println("Fund requested exceeds limit! Withdraw unsuccessful");
        cautionMessage();
    }
}

public class Test {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Type_1 t1 = new Type_1(sc.nextInt(), sc.next(), sc.nextDouble());
        t1.deposit(sc.nextDouble());
        t1.withdraw(sc.nextDouble());
        System.out.println("Type_1 balance: " + t1.getBalance());
        Type_2 t2 = new Type_2(sc.nextInt(), sc.next(), sc.nextDouble());
        t2.deposit(sc.nextDouble());
        t2.withdraw(sc.nextDouble());
        System.out.println("Type_2 balance: " + t2.getBalance());
