import java.util.*;
interface Generatable {
    double billGenerate(int units);
}

class PowerBill {
    // █ FILLED BY STUDENT: Define class Domestic
    private class Domestic implements Generatable {
        public double billGenerate(int units) {
            if (units <= 100) return units * 1.6;
            else if (units <= 200) return units * 2.5;
            else return units * 5.6;
        }
    }

    // █ FILLED BY STUDENT: Define class Commercial
    private class Commercial implements Generatable {
        public double billGenerate(int units) {
            if (units <= 100) return units * 5.6;
            else if (units <= 200) return units * 7.5;
            else return units * 20.0;
        }
    }

    public Generatable getDomesticBill() { return new Domestic(); }
    public Generatable getCommercialBill() { return new Commercial(); }
}

public class BillingTest {
    public static double getBill(int units, String type) {
        // █ FILLED BY STUDENT: create PowerBill, call correct factory, call billGenerate
