    public static char[] replace(char[] arr, int i, char c) {
        try {
            arr[i] = c;
        } catch (ArrayIndexOutOfBoundsException e) {
            if (i < 0) {
                throw e;
            } else {
                arr[arr.length - 1] = c;
            }
        }
        return arr;
    }

